package java.util.function;
public interface LongUnaryOperator { long applyAsLong(long value); default LongUnaryOperator compose(final LongUnaryOperator p){java.util.Objects.requireNonNull(p);return new LongUnaryOperator(){public long applyAsLong(long v){return LongUnaryOperator.this.applyAsLong(p.applyAsLong(v));}};} default LongUnaryOperator andThen(final LongUnaryOperator p){java.util.Objects.requireNonNull(p);return new LongUnaryOperator(){public long applyAsLong(long v){return p.applyAsLong(LongUnaryOperator.this.applyAsLong(v));}};} static LongUnaryOperator identity(){return new LongUnaryOperator(){public long applyAsLong(long v){return v;}};} }
